-- 계절별·지역별 인기 어종 보강 (2026-10-09 조사)
--  근거: 수산자원공단 낚시어선 어획량 조사(2023~2025, 어종별 1위 갈치·갑오징어·주꾸미·문어·방어/한치)
--        해양경찰청 낚시어선 주어업지(공공데이터포털, 해경서×계절 76종, 2022) 해역별 집계
--        언론 보도(해수부·국립수산과학원 인용). 방법·미끼·팁은 일반 안내용(공식 근거 약함)
--  1) 새 어종 10종 (사용자가 같은 이름을 이미 추가했으면 그 행을 공식 어종으로 올림)
--  2) species_seasons: 기존 행은 조사값으로 갱신, 없는 (어종, 해역)은 추가
--  금어기·금지체장은 closed_season_rules에서 따로 관리 (이 파일에서 다루지 않음)

-- 1) 새 어종
insert into public.species (name_ko, name_std, difficulty, water_type, code, status) values
  ('갈치',     '갈치',     2, 'sea', 'hairtail',               'official'),
  ('방어',     '방어',     4, 'sea', 'yellowtail',             'official'),
  ('부시리',   '부시리',   4, 'sea', 'goldstriped_amberjack',  'official'),
  ('한치',     '창꼴뚜기', 2, 'sea', 'swordtip_squid',         'official'),
  ('가자미',   '참가자미', 1, 'sea', 'righteye_flounder',      'official'),
  ('도다리',   '문치가자미', 2, 'sea', 'marbled_flounder',     'official'),
  ('열기',     '불볼락',   1, 'sea', 'goldeye_rockfish',       'official'),
  ('임연수어', '임연수어', 1, 'sea', 'atka_mackerel',          'official'),
  ('민어',     '민어',     4, 'sea', 'brown_croaker',          'official'),
  ('대문어',   '대문어',   3, 'sea', 'giant_octopus',          'official')
on conflict (name_ko) do update
  set name_std = excluded.name_std, difficulty = excluded.difficulty, water_type = excluded.water_type,
      code = excluded.code, status = 'official'
  where public.species.status = 'user';

